#!/usr/bin/env node
/**
 * Regenerate api/_lib/inference-benchmark.js by running the real vendored
 * model (models/mnist-8.onnx, ONNX model zoo, MIT) over the deterministic
 * benchmark vectors.
 *
 * The benchmark vectors exist so the platform can verify a node's proof job
 * WITHOUT running inference server-side: every vector's expected output was
 * produced by actually executing the model here, once, and recording the
 * argmax. Run this again only when the model or the vector set changes:
 *
 *   node node-operator/scripts/generate-benchmarks.mjs
 *
 * It prints the generated file path and a summary line per vector.
 */

import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { runMnist, BENCHMARK_SEEDS, benchmarkVector } from '../src/inference.js';

const here = dirname(fileURLToPath(import.meta.url));
const outPath = join(here, '..', '..', 'api', '_lib', 'inference-benchmark.js');

const vectors = [];
for (const seed of BENCHMARK_SEEDS) {
	const input = benchmarkVector(seed);
	const result = await runMnist(input);
	vectors.push({
		seed,
		input_b64: Buffer.from(input.buffer, input.byteOffset, input.byteLength).toString('base64'),
		expected_top1: result.top1,
		logits_sha256: result.logitsSha256,
	});
	console.log(`seed=${seed} top1=${result.top1} logits_sha256=${result.logitsSha256.slice(0, 16)}...`);
}

const fileHash = createHash('sha256')
	.update(JSON.stringify(vectors.map((v) => [v.seed, v.expected_top1, v.logits_sha256])))
	.digest('hex');

// Model file hash is pinned so the platform records the exact artifact the
// vectors were produced with.
const modelBytes = readFileSync(join(here, '..', 'models', 'mnist-8.onnx'));
const modelSha256 = createHash('sha256').update(modelBytes).digest('hex');

const source = `// GENERATED by node-operator/scripts/generate-benchmarks.mjs - do not hand-edit.
// Every expected output below was produced by REALLY running the vendored
// MNIST-8 model (ONNX model zoo, MIT) on the vector next to it. The platform
// uses these as the proof-of-compute benchmark for the open inference
// network: a node proves it can run real inference by reproducing the
// recorded argmax on its assigned vector. Regenerate with:
//
//   node node-operator/scripts/generate-benchmarks.mjs

export const PROOF_MODEL = 'mnist-8';
export const PROOF_MODEL_SHA256 = '${modelSha256}';
export const PROOF_VECTOR_SET_SHA256 = '${fileHash}';

// input_b64: base64 of 784 little-endian float32 values (28x28 grayscale,
// MNIST layout, values in [0,1]). expected_top1: argmax of the 10 logits the
// model emits for that input. logits_sha256: recorded for audit, not
// enforced (execution providers may differ in the last ulp; argmax is the
// stable contract).
export const PROOF_VECTORS = [
${vectors
	.map(
		(v) => `	{
		seed: ${v.seed},
		input_b64:
			'${v.input_b64}',
		expected_top1: ${v.expected_top1},
		logits_sha256: '${v.logits_sha256}',
	}`,
	)
	.join(',\n')}
];

export function decodeProofInput(b64) {
	const bytes = Buffer.from(b64, 'base64');
	return new Float32Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 4);
}
`;

writeFileSync(outPath, source);
console.log(`wrote ${outPath}`);
console.log(`model sha256=${modelSha256}`);
console.log(`vector set sha256=${fileHash}`);
